def get_path_to_module():
    logs_dir = 'logs'
    try:
        import hran_elementmanager2g
        module_path = path.dirname(str(hran_elementmanager2g.__file__))
        module_path = path.join(module_path, logs_dir)
    except NameError:
        module_path = "{}{}".format(path.dirname(return_ironpython_path()),
                                    ("\\Lib\\site-packages\\hran_elementmanager2g\\logs"))
    if not path.exists(module_path):
        makedirs(module_path)
    return module_path


class BcfGenerator(EquipmentControl.Settings.AbstractBtsSettings):
    def _create_new_bcf(self, *args):
        r"""
        Creates a .NET object of type BcfControl in order to be able to use BcfControl methods in it.
        :return: object of type BcfControl.
        """
        self.settings = EquipmentControl.Settings.BcfSettings
        newBTS = self.settings(self.settings.BcfType.bcf)
        newBTS.Cabinettype = 'bcf'
        try:
            newBTS.BcfNumber = int(self.bcfnumber)
        except ValueError as e:
            raise type(e)('Invalid BCF number. Did you enter a NUMBER?')
        newBTS.Ipaddress = self.host
        newBTS.TcpPort = self.port
        newBTS.Password = self.password
        EquipmentControl.EquipmentControlContainer.EControl = EquipmentControl.NalfEquipmentControl(None)
        # print(clr.GetClrType(EquipmentControl.Settings.AbstractBtsSettings).IsAssignableFrom(newBTS.GetType()))
        return EquipmentControl.Controls.BcfControl(
            newBTS)  # bcfcontrol(bcfsettings): default constructor with parameters

    def create_bcf(self, host='192.168.255.131', port=27500, password='', bcfnumber='1024'):
        r"""
        Interface to create .NET BcfControl object
        :param host: BCF host
        :param port: BCF port
        :param password: BCF password
        :param bcfnumber: BCF number
        :return: .NET BCF object of type EquipmentControl.Control.BcfControl
        """
        self.host = host
        self.port = port
        self.password = password
        self.bcfnumber = bcfnumber
        return self._create_new_bcf(host, port, password, bcfnumber)


class ElementManager2G(object):
    def __init__(self, host='192.168.255.131', port=27500, password='HxVs13Gr', bcfnumber='1024', debug=True):
        r"""
        Will call a BCF generator method with specified input parameters.
        :param host: string, local IP to BCF, default 192.168.255.131
        :param port: int, local port for direct element manager connection, default 27500
        :param password: string, BCF password
        :param bcfnumber: string, BCF id as declared in BSC
        :param debug: any type that will evaluate to True, will print files in c:\temp\ with debug information about
        .NET calls, low level m_bts messages and BCF alarms.
        """
        self.host = host
        self.bcfnumber = bcfnumber
        self.debug = debug
        self.bcf = BcfGenerator().create_bcf(host, port, password, bcfnumber)
        # subscribe to connection events
        self.watcher_connection = self.bcf.OnBtsConnected
        self.watcher_connection += self.callback_connect
        self.watcher_disconnection = self.bcf.OnBtsDisconnected
        self.watcher_disconnection += self.callback_disconnect
        # subscribe to alarm events
        self.watcher_alarm = self.bcf.OnAlarmObserved
        self.watcher_alarm += self.callback_alarm
        self.alarm_dict = {}
        self.is_connected = False
        self.module_path = get_path_to_module()
        self.sw_version = {
            'active': 'not_run',
            'passive': 'not_run'
        }
        if self.debug:
            IVTools.CommonModules.TraceLogModule.TraceLog.WriteTraceToFile(
                self.module_path + '\\{:%b %d, %Y, %H %M %S}'.format(datetime.now()) + '.txt')

    def callback_connect(self, sender, event_args):
        self.is_connected = True
        print('Event: Connected to BCF id: ', self.bcfnumber)

    def callback_disconnect(self, sender, event_args):
        self.is_connected = False
        print('Event: Disconnected from BCF id: ', self.bcfnumber)

    def callback_alarm(self, sender, event_args):
        message = 'Event: Alarm = ' + str(event_args.Value.AlarmDetail)
        self.alarm_dict = {str(event_args.Value.RealTime): message}  # TODO: get all alarm fields
        print(message)

    def connect_to_bcf(self):
        r"""
        Keyword used to connect to BCF. Connection attempt is handled internally for 6 times until successful.
        Upon connection success BCF State will be printed (ex. "BCF state is: Supervisory').
        If retries are unsuccessful, KW will fail.
        Connection is not automatically closed during script execution (and should also not be dropped by BCF) unless
        disconnect method is called explicitly.
        In case of unhandled/unexpected script failure, BCF will automatically close any unresponsive connection
        after 15 seconds.

        Example:
        | ${success} | Connect To BCF

        :return: True if connection successful.
        """
        # event_info = clr.GetClrType(EquipmentControl.Controls.BcfControl).GetEvent("OnAlarmObserved")
        # print(event_info.GetAddMethod().Name)  # useful if needed to hook to OnAlarmObserved event handler
        # print(event_info.GetRemoveMethod().Name)
        if not self.is_connected:
            print('Trying to connect to BCF {}...'.format(self.bcfnumber))
            for i in range(6):
                if self.bcf.Connect():
                    print('Successfully connected to 2G BTS, BCF id: {}'.format(self.bcfnumber))
                    self.bcf.GetUpdateBcfInfo()  # Mandatory, will populate bcfsettings class
                    print('BCF state is: {}'.format(self.bcf.BcfState()))
                    return self.is_connected
                else:
                    if self.bcf.LastError.find('Connection failed.') != -1:
                        raise ConnectionException('Cannot connect to BCF: wrong parameters')
                    if str(self.bcf.LastError).find('Unable to connect: 65001') != -1:
                        print('Attempting connection to BCF: another Site Manager already connected')
                    print('Try #{}/5: connect to BCF {}'.format(i, self.bcfnumber))
                    if i == 5:
                        raise ConnectionException('Cannot connect to BCF: another Site Manager already connected')
                    sleep(10)
        else:
            return "No need to connect() because we're already connected..."

    def _wait_for_supervisory(self):
        ctr = 0
        while self.bcf.BcfState() != 'Supervisory':
            ctr += 1
            if ctr > 80:
                print('BTS did not properly change to Supervisory state after commissioning!')
                raise CommissioningException('Commissioning error: BTS did not properly change to '
                                             'Supervisory state after commissioning; Please check SCF file!')
            sleep(23)
            print('BCF site name after commissioning: {}'.format(self.bcf.CurrentSiteName()))
            print("BCF state: {}".format(self.bcf.BcfState()))
            print("BCF object state: {}".format(self.bcf.BcfObjectState()))
        return True

    def _wait_for_commissioning(self):
        ctr = 0
        while self.bcf.BcfState() == 'Supervisory':  # if trying to load a SCF to an already commissioned BCF
            ctr += 1
            if ctr > 40:
                print('BTS did not change from Supervisory to Commissioning state!')
                raise CommissioningException('Commissioning error: BTS did not change from Supervisory to '
                                             'Commissioning state; please check SCF file!')
            else:
                sleep(6)  # wait for BTS to switch to Commissioning state
                print('BTS did not yet change from Supervisory to Commissioning state, still waiting...')
        return self._wait_for_supervisory()

    def check_bcf_state_before_scf_upload(self, bcf_state='Commissioning', state_check_timeout=600):
        counter = state_check_timeout
        while bcf_state not in ['Commissioning', 'Supervisory']:
            if counter < 60:
                print('BTS did not properly left state {} after {} seconds!'.format(bcf_state, state_check_timeout))
                raise CommissioningException('Commissioning error: BTS did not properly left'
                                             'state {} after {} seconds!'.format(bcf_state, state_check_timeout))
            sleep(60)
            bcf_state = self.bcf.BcfState()
            print('Current state {}'.format(bcf_state))
            counter -= 60

    def bts_commissioning(self, scf_file, retry=3, state_check_timeout=600):
        r"""
        Keyword used to load commissioning (.xml) file to BCF.
        Will fail if no connection to BTS is available or if BCF has improper state after commissioning
        (ie. 'Supervisory') or if BCF file is incorrect (not accepted by BCF).
        SCF file has to have some XML nodes renamed from default values when loaded with this interface and therefore
        it needs to be processed by XMLParser prior to loading to BCF. This is done automatically and transparent
        to the user.

        Example:
        | ${success} | BTS Commissioning

        :param scf_file: string, full path to .xml file (i.e. c:\\temp\\scf_file.xml)
        :param retry: int, optional, number of retries to load commissioning file to BCF, default 3.
        :param state_check_timeout: int, optional, maximum wait time for BCF Commissioning or Supervisory state before loading SCF
        :return: True if successful and if BCF state changed properly, fails otherwise
        """
        if self.is_connected:
            print('Commissioning 2G BTS using file: {}'.format(scf_file))
            XMLParser(scf_file, scf_file + '_automated').update_gsm_scf()
            print('BCF site name before commissioning: {}'.format(self.bcf.CurrentSiteName()))
            success = False
            starting_state = self.bcf.BcfState()
            print('BCF state before commissioning: {}'.format(starting_state))
            checks = {
                'Commissioning': self._wait_for_supervisory,
                'Supervisory': self._wait_for_commissioning
            }
            self.check_bcf_state_before_scf_upload(bcf_state=starting_state, state_check_timeout=state_check_timeout)
            while retry > 0:
                success = self.bcf.RequestCommissioningUpdate(scf_file + '_automated')
                if success:
                    print('Done loading SCF file.')
                    try:
                        return checks[starting_state]()
                    except KeyError:
                        return checks['Commissioning']()
                else:
                    retry -= 1
                    print('Failed to load scf, retries left: {}'.format(retry))
                    sleep(10)
            else:
                raise CommissioningException('Commissioning error, please check SCF file!')
        else:
            raise ConnectionException("There's no connection to 2G BTS. Did you connect() first?")

    def bts_uncommissioning(self, retry=3):
        r"""
        Keyword used to uncommission BCF.
        Will fail if no connection to BTS is available or if BCF has improper state after uncommissioning
        (ie. 'Commissioning') or if BCF refuses uncommissioning command for some reason.

        Example:
        | ${success} | BTS Uncommissioning

        :param retry: int, optional, number of retries to send uncommissioning command to BCF, default 3.
        :return: True if successful and if BCF state changed properly
        """
        ctr = 0
        success = False
        if self.is_connected:
            while retry > 0:
                success = self.bcf.RequestUndoCommissioning()
                if success:
                    retry = 0
                    print('Uncommissioning command sent successfully.')
                else:
                    retry -= 1
                    print('Failed to uncommission, retries left: {}'.format(retry))
                    sleep(10)
            if success:  # TODO: if BCF is already in Commissioning state, need to wait for UNKNOWN state
                while self.bcf.BcfState() != 'Commissioning':
                    ctr += 1
                    if ctr > 40:
                        self.disconnect_from_bcf()
                        raise CommissioningException('ERROR: BTS did not properly change state after uncommissioning!')
                    sleep(15)
                    print("BCF state: {}".format(self.bcf.BcfState()))
                    print("BCF object state: {}".format(self.bcf.BcfObjectState()))
                return True
            else:
                self.disconnect_from_bcf()
                raise CommissioningException('ERROR: BTS did not properly change state after uncommissioning!')
        else:
            raise ConnectionException("There's no connection to 2G BTS. Did you connect() first?")

    def bts_get_sw_versions(self):
        r"""
        Keyword used to fetch active and passive software packages from connected BCF.
        Information is obtained by connecting via SSH to FSMx boards and telnet to other boards (yet to be implemented).
        Returns a dictionary with active and passive SW data (or None if unavailable) if successful.
        Will fail if no connection to BTS is available.

        Example:
        | ${sw_package} | BTS Get SW Versions

        Result:
        ${sw_package} = {'passive': 'BTSR1653.C9X', 'active': 'BTSR1653.F5X'}

        :return: Dictionary with two keys, active and passive.
        """
        hw_info = self.get_hw_information()
        result = None
        if 'FSM' in hw_info:
            if self.enable_ssh_on_fsm():
                result = self._get_fsmf_sw()
            else:
                print('Cannot fetch BTS SW versions. Connect to BTS via SSH failed.')
        elif 'ESM' in hw_info:
            if self.enable_telnet():
                result = self._get_esm_sw()
            else:
                print('Cannot fetch BTS SW versions. Connect to ESM via telnet failed.')
        else:
            result = self._get_other_sw()
        if result is not None:
            self.sw_version = result
        return self.sw_version

    def find_bts_trx_objects(self, btsnumber='BTS-1'):
        r"""
        Keyword used to get TRXs connected to a BTS. Returns list of TRX IDs connected to given BTS.
        Will fail if no connection to BTS is available.

        Example:
        | ${trxs} | Find BTS TRX Objects | 'BTS-1"

        Result:
        ${trxs} =
        ['TRX id: 13', 'TRX id: 14', 'TRX id: 15', 'TRX id: 16', 'TRX id: 17', 'TRX id: 18']

        :param btsnumber: string used in query, ie. BTS-1, BTS-2, etc...
        :return: list of all TRXs found connected to BTS
        """
        if self.is_connected:
            trxs = []
            for trx in self.bcf.FindBtsTrxObjects(btsnumber):
                trxs.append('TRX id: {}'.format(trx))
            return trxs
        else:
            raise ConnectionException("There's no connection to 2G BTS. Did you connect() first?")

    def get_related_trxs(self, radiomodule='RM-1.1'):
        r"""
        Keyword to used to get all TRXs connected to a given RF module (RM-1.1) and TX/RX paths (TxMain, RxMain, RxDiv).
        Returns a dictionary if successful. Will fail if no connection to BTS is available.

        Example:
        | ${trxs} | Get Related TRXs | 'RM-2.1'

        Result:

        TRX-1: TxMain, RxMain
        TRX-3: TxMain, RxMain
        TRX-2: TxMain, RxMain
        TRX-5: TxMain, RxMain
        TRX-4: TxMain, RxMain
        TRX-6: TxMain, RxMain

        :param radiomodule: string, ie. RM-1.1
        :return: Dictionary where TRX name is the key and value is list of TX/RX path types in given RM for this TRX.
        (ie. {"TRX-1": ["TxMain", "RxMain", "RxDiv"]})
        """
        if self.is_connected:
            trx_list = []
            rel_trxs = dict(self.bcf.GetRelatedTrxs(radiomodule))
            for (trx, paths) in rel_trxs.items():
                trx_list.append('{}: {}'.format(trx, ', '.join(paths)))
            return trx_list
        else:
            raise ConnectionException("There's no connection to 2G BTS. Did you connect() first?")

    def get_current_states_of_trxs_and_bcf(self):
        r"""
        Keyword to get states of all TRXs and BCF. Will fail if no connection to BTS is available.

        Example:
        | ${states} | Get Current States of TRXs and BCF

        Result:
        {'TRX-15': 'Enabled', 'BCF-255': 'Enabled', 'TRX-25': 'Enabled', 'TRX-1': 'Enabled',
        'TRX-27': 'Enabled', 'TRX-3': 'Enabled', 'TRX-13': 'Enabled'}

        :return: Dictionary with TRX and BCF states (key: BCF/TRX-no, value: state).

        """
        if self.is_connected:
            trx_bcf_state_dict = {}
            for item in self.bcf.GetCurrentStatesOfTrxAndBcf():
                trx_or_bcf, state = item.split(': ', 1)
                trx_bcf_state_dict[trx_or_bcf] = state
            return trx_bcf_state_dict
        else:
            raise ConnectionException("There's no connection to 2G BTS. Did you connect() first?")

    def get_hw_information(self):
        r"""
        Keyword will return nested list of connected HW (boards, RMs), their versions and #SNs.
        Will fail if no connection to BTS is available.

        Example:
        | ${hw_info} | Get HW Information

        Result:
        ${hw_info} = 'BCF HW info:
            HWUnitIdentity: FHX:472132A-128, owner: BCF-1, HWVersion: 102, SerialNumber:  L1112307842,
            HWUnitIdentity: FSM:472181A     -1, owner: BCF-1, HWVersion: 104, SerialNumber:  L1160614589,
            HWUnitIdentity: FHX:472132A-64, owner: BCF-1, HWVersion: 203, SerialNumber:  L1113511166,
            HWUnitIdentity: FHX:472132A-0, owner: BCF-1, HWVersion: 102, SerialNumber:  L1112512880,
            '

        :return: List of available HW with info pertaining all modules connected to BCF
        """
        if self.is_connected:
            return 'BCF HW info: \n{}'.format(self.bcf.FindSmallHwInformation())
        else:
            raise ConnectionException("There's no connection to 2G BTS. Did you connect() first?")

    @staticmethod
    def enable_telnet():
        r"""
        Keyword to activate telnet on ESMx boards. Is generally used as part of other KWs and not independently.
        KW sends specially crafted UDP packets to BTS, therefore it's called multiple times to insure success.
        Will return True if successful. Will fail if no connection to BTS is available.
        Since delivery of TAT-6971, enable_telnet can be used as a static method.

        Example:
        | ${success} | Enable telnet

        :return: True or False
        """
        with CreateFakeBcf() as fake:
            if fake.bcf.EnableTelnet(fake.host, 33560) and fake.bcf.EnableFTP(fake.host, 33560):
                for i in range(4):
                    fake.bcf.EnableTelnet(fake.host, 33560) and fake.bcf.EnableFTP(fake.host, 33560)
                return True
            else:
                return False

    @staticmethod
    def disable_telnet():
        r"""
        Keyword to disable telnet on ESMx boards.
        KW sends specially crafted UDP packets to BTS, therefore it's called multiple times to insure success.
        Will return True if successful. Will fail if no connection to BTS is available.

        Example:
        | ${success} | Disable Telnet And Ftp

        :return: True of False
        """
        with CreateFakeBcf() as fake:
            if fake.bcf.DisableTelnet(fake.host, 33560) and fake.bcf.EnableFTP(fake.host, 33560):
                for i in range(4):
                    fake.bcf.DisableTelnet(fake.host, 33560) and fake.bcf.EnableFTP(fake.host, 33560)
                return True
            else:
                return False

    @staticmethod
    def is_gsm_pingable(gsm_hostname):
        r"""
        Keyword used to check if GSM BTS is reachable with ping.
        """
        cmd = "ping -n 3 {}".format(gsm_hostname)
        process = subprocess.Popen(cmd, stdout=subprocess.PIPE, shell=True)
        stdout = process.communicate()[0]
        return process.wait() == 0, stdout

    @staticmethod
    def wait_for_GSM_sm_to_be_reachable(gsm_hostname, timeout=200):
        r"""
        Keyword pings the gsm hostname until it is reachable, unless timeout expires. In that case it will raise Error
        """
        for i in range(int(timeout) / 3 + 1):
            is_pingable, stdout = ElementManager2G.is_gsm_pingable(gsm_hostname)
            print('INFO: Ping no. {} output: {}'.format(i, stdout))
            if not is_pingable:
                continue
            else:
                print('INFO: GSM Target became reachable!')
                return True
        raise ConnectionException('Target didn\'t become reachable in {} seconds'.format(timeout))

    @staticmethod
    def wait_for_GSM_sm_to_be_not_reachable(gsm_hostname, timeout=200):
        r"""
        Keyword pings the gsm hostname until it is not reachable anymore, unless timeout expires. In that case it will raise Error
        """
        for i in range(int(timeout) / 3 + 1):
            is_pingable, stdout = ElementManager2G.is_gsm_pingable(gsm_hostname)
            print('INFO: Ping no. {} output: {}'.format(i, stdout))
            if is_pingable:
                continue
            else:
                print('INFO: GSM Target stopped to be reachable!')
                return True
        raise ConnectionException('Target didn\'t become unreachable in {} seconds'.format(timeout))

    def enable_ssh_on_fsm(self):
        r"""
        Keyword to activate SSH daemon on FSMx boards. Is generally used as part of other KWs and not independently.
        KW sends specially crafted UDP packets to BTS, therefore it's called multiple times to insure success.
        Will return True if successful. Will fail if no connection to BTS is available.

        Example:
        | ${success} | Enable SSH On FSM

        :return: True or False
        """
        if self.bcf.EnableSshFsmf(self.host, 33560):
            for i in range(4):
                self.bcf.EnableSshFsmf(self.host, 33560)
            return True
        else:
            return False

    def _get_fsmf_sw(self):
        r"""Function to read SW versions from FSMx boards. Needs to have SSH enabled prior to use.
        Returns dictionary of active/passive """
        for i in range(30):
            try:
                ssh_con = sshlib.SSH()
                if not ssh_con.open(self.host, 22, 'toor4nsn', 'HkjunbTacdr1@3$', 10):
                    ssh_con.open(self.host, 22, 'toor4nsn', 'oZPS0POrRieRtu', 10)
                ssh_con.write('ll /ffs |grep run | grep -oE "[^/]+$"\n')  # Should return fs1 or fs2
                running_filesystem = ssh_con.read_until(">", 2)
                running = ''
                for item in running_filesystem.splitlines():
                    if str(item).strip().find("fs1") != -1:
                        running = str(item).strip()
                        break
                    if str(item).strip().find("fs2") != -1:
                        running = str(item).strip()
                        break
                active_path = "/ffs/{}/som/srv".format(running)
                if running == 'fs1':
                    passive_filesystem = 'fs2'
                else:
                    passive_filesystem = 'fs1'
                passive_path = "/ffs/{}/som/srv".format(passive_filesystem)
                ssh_con.write("ls {}\n".format(active_path))
                active_version = ssh_con.read_until(">", 2)
                for line in active_version.splitlines():
                    if line.find("BTSR") != -1:
                        self.sw_version['active'] = str(line).split()[0].strip()
                        break
                    self.sw_version['active'] = 'not_known'
                ssh_con.write("ls {}\n".format(passive_path))
                passive_version = ssh_con.read_until(">", 2)
                for line in passive_version.splitlines():
                    if line.find("BTSR") != -1:
                        self.sw_version['passive'] = str(line).split()[0].strip()
                        break
                    self.sw_version['passive'] = 'not_known'
                ssh_con.close()
                ssh_con = None
                return self.sw_version
            except Exception as msg:
                print("Error with sshlib.open {} - {}".format(msg, i))
                sleep(2)
            finally:
                if ssh_con:
                    ssh_con.close()
                    ssh_con = None

    def _get_esm_sw(self):
        r"""Function to read SW versions from ESMx boards. Enables telnet beforehand and leaves it enabled.
        Returns dictionary of active/passive """
        for i in range(30):
            try:
                telnet = telnetlib.Telnet()
                telnet.open(self.host, 23, 10)
                telnet.read_until("login: ", 2)
                telnet.write("root" + "\n")
                telnet.read_until("Password: ", 2)
                telnet.write("HkjunbTacdr1@3$" + "\n")
                telnet.read_until("#", 2)
                telnet.write("cd /tmp/active/som/srv\n")
                telnet.read_until("#", 2)
                telnet.write("ls\n")
                resp = telnet.read_until("#", 2).split()
                print('INFO: _get_esm_sw, BTS response to ls in /tmp/active/som/srv: {}'.format(resp))
                for line in resp:
                    if (line.find("BTS") == 0):
                        self.sw_version['active'] = line.split('\r')[0]
                        break
                if (line.find("BTS") != 0):
                    self.sw_version['active'] = 'not_known'

                telnet.write("cd /tmp/passive/som/srv\n")
                telnet.read_until("#", 2)
                telnet.write("ls\n")
                resp = telnet.read_until("#", 2).split()
                print('INFO: _get_esm_sw, BTS response to ls in /tmp/passive/som/srv: {}'.format(resp))
                for line in resp:
                    if (line.find("BTS") == 0):
                        self.sw_version['passive'] = line.split('\r')[0]
                        break
                if (line.find("BTS") != 0):
                    self.sw_version['passive'] = 'not_known'
                telnet.write("exit\n")
                return self.sw_version
            except Exception as msg:
                print("Error with telnetlib.open {} - {}".format(msg, i))
                sleep(2)
            finally:
                if telnet:
                    telnet.close()
                    telnet = None

