    def _check_ftp_port(self):
        import socket
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            s.bind(("127.0.0.1", 21))
        except socket.error as e:
            if e.errno == 98:
                raise ConnectionException('Cannot start SWDL because port 21 is already in use!')
            else:
                print(e)
                raise ConnectionException('Cannot start SWDL because port 21 cannot be accessed!')
        s.close()

    def request_sw_update(self, sw_path, load_all_files=True):
        r"""
        Keyword to perform SWDL/SW update to 2G BTS. It expects a BTS masterfile (ie. BTSR1653.F7X) as input
        and optionally a True/False flag to trigger download of all files to BTS or just new ones.
        Will return True if SWDL succeeds and False otherwise. Will fail if no connection to BTS is available.

        Example:
        | ${success} | Request SW Update | ${path_to_masterfile} | ${load_all_files}

        Result:
        Starting SW download. Please wait patiently ..
        SwUpdate success
        ${success} = 'True'

        :param sw_path: string, full path to BTS masterfile (ie. C:\\temp\\BTSR1653.F7X)
        :param load_all_files: boolean, True or False
        :return: True or False
        """
        if self.is_connected:
            self._check_ftp_port()
            validity_flag = True
            rx = r'BTS\w{5}\.\w{3}$'
            # make checks
            m = search(rx, sw_path)
            if not m:
                print('Last item from path must be a BTS Masterfile name <BTS..... . ...>')
                validity_flag = False
            if not path.isfile(sw_path):
                print('File {} does not exist'.format(sw_path))
                validity_flag = False
            # if checks successful, do upgrade
            if validity_flag:
                print('Starting SW download. Please wait patiently ..')
                if self.bcf.RequestSWUpdate(sw_path, load_all_files):
                    print('SwUpdate success')
                else:
                    print('SwUpdate from file: {} failed'.format(sw_path))
                    validity_flag = False
            return validity_flag
        else:
            raise ConnectionException("There's no connection to 2G BTS. Did you connect() first?")

