    def unblock_bcf(self):
        r"""
        Keyword to unblock BCF. Please wait patiently after function return for BCF to become operational!
        :return: True if BCF Unblock successful AND connection to BCF is restored after unblock.
        False it BCF Unblock command was unsuccessful.
        ConnectionException if no connection to BCF is available or if we can't reconnect to BCF after unblock.
        """
        if self.is_connected:
            if self.bcf.Unblock():
                print('BCF Unblock command successfully sent, awaiting BCF disconnection/reconnection...')
                sleep(30)
                for i in range(30):
                    if self.is_connected:
                        print('BCF successfully reconnected after BCF unblock operation.')
                        return True
                    print('Still waiting for BCF reconnection event...')
                    sleep(30)
                raise ConnectionException("Can't reconnect to 2G BCF after BCF unblock.")
            else:
                print("Could not unblock BCF. Are you sure it's blocked...?")
                return False
        else:
            raise ConnectionException("There's no connection to 2G BTS. Did you connect() first?")

