    def check_current_states_of_all_bts(self, expected_bts_state='Enabled', allow_negative_result=False):
        r"""
        Keyword used to check states of all BTSs connected to BCF and compare them to an expected state.
        This keyword will raise an UnexpectedObjectState exception if current BTS state is different from expected and
        allow_negative_result is set to False. If allow_negative_result is set to True, keyword will only return False
        but raise no exception.

        Result:
        BTS-1 state is Blocked (we expected Enabled)
        BTS-2 state is Blocked (we expected Enabled)
        BTS-3 state is Blocked (we expected Enabled)
        Not all BTSs states are as expected: Enabled
        exception.UnexpectedObjectState: ('BTS state is different from expected state!',
        {'BTS-3': 'Blocked', 'BTS-2': 'Blocked', 'BTS-1': 'Blocked'})

        :param expected_bts_state: Reference object state to which we compare actual BTSs state.
        Can be one of the following: Enabled, Disabled, Locked, Unlocked, Shutdown, Powersave, Blocked.
        :param allow_negative_result: True or False, will determine whether keyword will raise an exception or just
        return False if expected BTSs state is not met.

        :return:
        True if all BTSs have expected state + dictionary with BTS no. as keys and states as values
        False if allow_negative_result=True and one of more BTSs have different state than expected + dictionary with
        BTS no. as keys and states as values
        Fail if allow_negative_result=False and one of more BTSs have different state than expected + dictionary with
        BTS no. as keys and states as values
        """
        if self.is_connected:
            sw = 0
            bts_dict = {}
            for bts in self.bcf.FindBtsObjects():
                state = self.bcf.GetCurrentStatesOfBTSs(str(bts))
                bts_dict[bts] = str(state).strip("ObjectCurrentState: ")
                if bts_dict[bts] != expected_bts_state:
                    print("{} state is incorrect: {} (we expected {}!)".format(bts, bts_dict[bts], expected_bts_state))
                    sw = 1
                else:
                    print("{} state is correct: {}".format(bts, bts_dict[bts]))
            if sw == 0:
                print('All BTSs states are as expected: {}'.format(expected_bts_state))
                return True, bts_dict
            if sw == 1:
                if allow_negative_result:
                    print('Not all BTSs states are {}, as expected '.format(expected_bts_state))
                    return False, bts_dict
                else:
                    print('Not all BTSs states are as expected: {}'.format(expected_bts_state))
                    raise UnexpectedObjectState('BTS state is different from expected state!', bts_dict)
        else:
            raise ConnectionException("There's no connection to 2G BTS. Did you connect() first?")

    def check_current_state_of_bts(self, bts='BTS-1', expected_bts_state='Enabled', allow_negative_result=False):
        r"""
        Keyword used to check state of specified BTS and compare it to an expected state.
        This keyword will raise an UnexpectedObjectState exception if current BTS state is different from expected and
        allow_negative_result is set to False. If allow_negative_result is set to True, keyword will only return False
        but raise no exception.

        Output:
        BTS-2 state is correct: Enabled

        :param bts: string, BTSid, ie. BTS-1, BTS-2...
        :param expected_bts_state: Reference object state to which we compare actual BTSs state.
        Can be one of the following: Enabled, Disabled, Locked, Unlocked, Shutdown, Powersave, Blocked.
        :param allow_negative_result: True or False, will determine whether keyword will raise an exception or just
        return False if expected BTSs state is not met.

        :return:
        True if all BTS has expected state
        False if allow_negative_result=True and BTS has different state than expected
        Fail if allow_negative_result=False and BTS has different state than expected
        """
        if self.is_connected:
            state = str(self.bcf.GetCurrentStatesOfBTSs(str(bts))).strip("ObjectCurrentState: ")
            if state != expected_bts_state:
                print("{} state is incorrect: {} (we expected {}!)".format(bts, state, expected_bts_state))
                if allow_negative_result:
                    print('BTS state {} is different from expected state {}!'.format(state, expected_bts_state))
                    return False, state
                else:
                    raise (UnexpectedObjectState(
                        'BTS state {} is different from expected state {}!'.format(state, expected_bts_state)))
            else:
                print("{} state is correct: {}".format(bts, state))
                return True
        else:
            raise ConnectionException("There's no connection to 2G BTS. Did you connect() first?")

