    def get_bts_id_sector_id_mapping(self):
        r"""
        Keyword used to get mapping between BTS no (as declared in BSC) and sector.
        (Need custom equipmentcontrol.dll for this function)

        Output:
        {'BTS-3': 'BTS-312', 'BTS-2': 'BTS-311', 'BTS-1': 'BTS-310'}

        :return: Dictionary with key SECTOR and value BTS NUMBER
        """
        if self.is_connected:
            m = dict(findall(r"(BTS-\d+)\s-\s(BTS-\d)", sub("LSector", "BTS", self.bcf.DataUpdateInd())))
            m_list = list(dict((m[k], k) for k in m).values())
            bts_id_list = self.find_bts_objects()
            return dict(zip(bts_id_list, sorted(m_list)))
        else:
            raise ConnectionException("There's no connection to 2G BTS. Did you connect() first?")

